INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l65',2,9,65,'Jumbo versus the police','小象对警察','KS17 情态动词 must/have to(义务·不得不)、should/ought to(应该·责任·建议),以及 should have done / ought to have done(过去本应做而没做)(教材 L65 Key structures)主考;SD 三组:短语动词 let off/down/in/out、agree to do vs accept sth、dress up as vs dress(辅考)','去年圣诞节,马戏团老板吉米·盖茨决定送些礼物给儿童医院。他打扮成圣诞老人,在由6个漂亮姑娘组成的“仪仗队”的陪同下,骑上一头名叫江伯的小象,沿着城里的主要街道出发了。他本该知道警察绝不会允许这类事情发生。一个警察走过来告诉吉米,他应该走一条小路,因为江伯阻碍了交通。虽然吉米同意马上就走,但江伯却拒绝移动。15个警察不得不用很大的力气把它推离主要街道。警察虽然吃了苦头,但他们还是感到很有趣。“江伯一定有好几吨重,”一个警察事后这样说,“值得庆幸的是它没让我们抬它走。当然,我们应该逮捕它,但由于它一贯表现很好,这次我们饶了它。”','{"q":"Listen and answer — Why did the police have to push Jumbo off the main street?","options":["Jumbo was holding up the traffic and refused to move","Jumbo had attacked the crowd","Jumbo was badly hurt","Jumbo had run away from the circus"],"answer_index":0}'::jsonb,'{"title":"must / have to / should / ought to","intro":"KS17 表义务与建议:①must / have to = 必须、不得不(现在);过去的义务用 had to(must 没有过去式)。②should / ought to = 应该、理应(现在的建议、责任)。③过去本该做而没做:should have done / ought to have done(I should have taken a taxi 我本该打车的)。","table":{"headers":["用法","例子"],"rows":[["must / have to(现在义务)","I must write some letters tonight."],["had to(过去义务)","I missed the train, so I had to take a taxi."],["should / ought to(建议)","You ought to ask for permission."],["should/ought to have done(过去本应做)","I should have taken a taxi."]]},"specialRules":[{"rule":"SD 短语动词 let 各义不同:let sb off=饶恕/放过;let sb down=使失望;let sb in=让…进来;let sth out=放出去。","mark":"let off/down/in/out"},{"rule":"SD 易混词:agree to do=同意做某事;accept sth=接受某物。dress up (as)=(盛装)打扮成;dress=(一般地)穿衣。","mark":"agree/accept·dress up/dress"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l65',1,NULL,'Last Christmas, the circus owner, Jimmy Gates, decided to take some presents to a children''s hospital. Dressed up as Santa Claus and accompanied by a ''guard of honor'' of six pretty girls, he set off down the main street of the city riding a baby elephant called Jumbo.','去年圣诞节,马戏团老板吉米·盖茨决定送些礼物给儿童医院。他打扮成圣诞老人,在由6个漂亮姑娘组成的“仪仗队”的陪同下,骑上一头名叫江伯的小象,沿着城里的主要街道出发了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l65',2,NULL,'He should have known that the police would never allow this sort of thing. A policeman approached Jimmy and told him he ought to have gone along a side street as Jumbo was holding up the traffic.','他本该知道警察绝不会允许这类事情发生。一个警察走过来告诉吉米,他应该走一条小路,因为江伯阻碍了交通。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l65',3,NULL,'Though Jimmy agreed to go at once, Jumbo refused to move. Fifteen policemen had to push very hard to get him off the main street. The police had a difficult time, but they were most amused.','虽然吉米同意马上就走,但江伯却拒绝移动。15个警察不得不用很大的力气把它推离主要街道。警察虽然吃了苦头,但他们还是感到很有趣。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l65',4,NULL,'''Jumbo must weigh a few tons,'' said a policeman afterwards, ''so it was fortunate that we didn''t have to carry him.','“江伯一定有好几吨重,”一个警察事后这样说,“值得庆幸的是它没让我们抬它走。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l65',5,NULL,'Of course, we should arrest him, but as he has a good record, we shall let him off this time.''','当然,我们应该逮捕它,但由于它一贯表现很好,这次我们饶了它。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
